import{_ as i,o as e,c as a,aO as l}from"./chunks/framework.BFrk9dwu.js";const r="/recipes/crayfish.jpg",o="/recipes/crayfish/top-2.jpg",d="/recipes/crayfish/top-3.jpg",s="/recipes/crayfish/step-2-a.jpg",n="/recipes/crayfish/step-1-a.jpg",p="/recipes/crayfish/step-4-a.jpg",y=JSON.parse('{"title":"麻辣小龙虾","description":"小龙虾刷净剪头去虾线，辣椒花椒炒出红油，啤酒焖十分钟收汁裹壳的家常做法，含虾肉柴、不入味、汤寡的排查","frontmatter":{"date":"2026-11-29T04:00:58.000Z","title":"麻辣小龙虾","description":"小龙虾刷净剪头去虾线，辣椒花椒炒出红油，啤酒焖十分钟收汁裹壳的家常做法，含虾肉柴、不入味、汤寡的排查","categories":["life","recipes"],"permalink":"/pages/fc5ee0"},"headers":[],"relativePath":"life/recipes/crayfish.md","filePath":"life/recipes/crayfish.md","lastUpdated":1795873236000}'),c={name:"life/recipes/crayfish.md"};function g(h,t,f,_,m,u){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="麻辣小龙虾" tabindex="-1">麻辣小龙虾 <a class="header-anchor" href="#麻辣小龙虾" aria-label="Permalink to &quot;麻辣小龙虾&quot;">​</a></h1><div class="recipe-gallery"><img src="'+r+'" alt="麻辣小龙虾成品：大盆里堆满深红油亮的小龙虾，插着干辣椒和青花椒，底下露出黄瓜条"><img src="'+o+'" alt="特写：剥了一半壳的小龙虾，虾尾肉白嫩，浸在红油汤汁里"><img src="'+d+'" alt="一盆小龙虾配一杯冰啤酒"><img loading="lazy" src="'+s+'" alt="菜板上处理好的小龙虾，头部斜剪、虾背剪开，旁边一把剪刀"></div><p>小龙虾没什么讲究，就是够辣够油够味。洗和剪费时间，后面炒反而快：底料炒出红油，虾倒进去翻到全红，啤酒一浇盖盖焖十分钟，开盖收汁收到挂壳。一盆端上桌，壳红汁亮，手套一戴就开剥。</p><h2 id="用料" tabindex="-1">用料 <a class="header-anchor" href="#用料" aria-label="Permalink to &quot;用料&quot;">​</a></h2><p><strong>主料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>小龙虾</td><td>三斤，个头挑中等偏大的，太小没肉</td></tr><tr><td>黄瓜</td><td>一根，切条垫盆底，吸汁解辣</td></tr><tr><td>土豆</td><td>一个，切条，爱吃就加，不爱吃可以不放</td></tr></tbody></table><p><strong>底料与调料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>干辣椒段</td><td>一大把，怕辣去籽</td></tr><tr><td>青花椒</td><td>一小把，麻味主力，别省</td></tr><tr><td>火锅底料</td><td>一小块，红油和味道全靠它，不用再另调酱</td></tr><tr><td>姜、蒜</td><td>各一把，切片拍碎</td></tr><tr><td>八角、桂皮、香叶</td><td>各一点，增香去腥</td></tr><tr><td>啤酒</td><td>一罐，没过虾一半就行，去腥增香，没有就用料酒加水</td></tr><tr><td>生抽</td><td>两勺</td></tr><tr><td>食用油</td><td>要多，油少了炒不出红油</td></tr><tr><td>香菜、葱花、白芝麻</td><td>最后撒</td></tr></tbody></table><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li><p><strong>刷洗。</strong> 虾倒盆里泡二十分钟吐泥，然后用硬毛刷一只一只刷腹部和钳子缝，刷完换清水冲两遍。腹部和腮边是泥最多的地方，看着干净也得刷，不然一盆汤全是土味。</p><figure class="recipe-shots"><img loading="lazy" src="'+n+'" alt="不锈钢盆里泡着活小龙虾，盆边搭一把硬毛刷"></figure></li><li><p><strong>剪头去虾线。</strong> 剪掉头部前面三分之一（那一截是胃囊，最脏），尾巴中间那片捏住一拧，把虾线抽出来。</p><figure class="recipe-shots"><img loading="lazy" src="'+s+'" alt="菜板上处理好的小龙虾，头部斜剪、虾背剪开，旁边一把剪刀"></figure></li><li><p><strong>炒料。</strong> 锅烧热多放油，下姜蒜、干辣椒、青花椒、八角桂皮香叶，小火炸出香味，再下一小块火锅底料，慢慢炒到化开、油变深红。全程小火，底料一糊就发苦。</p></li><li><p><strong>下虾翻炒。</strong> 虾沥干水下锅，大火翻，看到壳从青变红、全身挂上红油就差不多了。水没沥干直接下锅会溅油，也炒不出红。</p><figure class="recipe-shots"><img loading="lazy" src="'+p+'" alt="炒锅里小龙虾在红油里翻炒，虾壳由青转红"></figure></li><li><p><strong>倒啤酒。</strong> 沿锅边倒一罐啤酒，加生抽，烧开后翻两下让虾都浸到汤里。啤酒比水香，去腥也更彻底。</p></li><li><p><strong>焖十分钟再收汁。</strong> 盖盖中小火焖十分钟，开盖转大火收汁，收到汤汁浓稠、能挂住虾壳为止。焖过头虾肉就柴了，十分钟刚好熟透。</p></li><li><p><strong>垫菜装盆。</strong> 盆底铺黄瓜条、土豆条，虾连汁一起倒上去。黄瓜垫底不只为解辣，还能把多余的油吸走，虾壳不会泡得发软。</p></li><li><p><strong>撒料上桌。</strong> 表面撒香菜段、葱花、白芝麻，喜欢更麻再补一把青花椒。趁热吃，凉了壳硬不好剥。</p><figure class="recipe-shots"><img src="'+r+'" alt="麻辣小龙虾成品：大盆里堆满深红油亮的小龙虾，插着干辣椒和青花椒，底下露出黄瓜条"></figure></li></ol><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><ul><li><strong>刷够、冲净</strong>：腹部和腮是泥窝，刷不干净整盆带土腥味。</li><li><strong>剪头剪前三分之一</strong>：胃囊在里面，不剪等于吃泥。</li><li><strong>虾线要抽</strong>：尾巴中间那片一拧就整根出来。</li><li><strong>油要多、火要小炒料</strong>：油少炒不出红油，火大辣椒花椒一黑就苦。</li><li><strong>啤酒代替水</strong>：去腥增香，汤汁也更浓。</li><li><strong>焖十分钟就收汁</strong>：时间长了肉柴，收汁到挂壳才入味。</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">常见翻车</p><p></p><ul><li><strong>虾肉发柴、缩成一小团</strong>：焖太久或者大火收汁收过头。</li><li><strong>不入味、只有壳有味</strong>：汤汁没收浓就起锅。</li><li><strong>发苦</strong>：辣椒花椒炸糊了，或者火锅底料炒糊了。</li><li><strong>汤寡、油水分离</strong>：油放太少，或者加了太多水。</li><li><strong>壳发软、剥不下来</strong>：装盆后泡在汤里太久，或者焖的时候水太多。</li></ul></div><p><a href="/life/recipes/">← 回菜谱总览</a></p>',14)])])}const k=i(c,[["render",g]]);export{y as __pageData,k as default};
